import AppKit

final class GlassCardController: NSViewController {
    override func loadView() {
        let glass = NSGlassEffectView()
        glass.translatesAutoresizingMaskIntoConstraints = false
        glass.cornerRadius = 16
        glass.tintColor = .controlAccentColor.withAlphaComponent(0.15)

        let label = NSTextField(labelWithString: "Liquid Glass")
        label.font = .preferredFont(forTextStyle: .title2)
        label.translatesAutoresizingMaskIntoConstraints = false
        glass.contentView = label

        NSLayoutConstraint.activate([
            label.centerXAnchor.constraint(equalTo: glass.centerXAnchor),
            label.centerYAnchor.constraint(equalTo: glass.centerYAnchor)
        ])
        view = glass
    }
}

import AppKit

final class BadgeView: NSView {
    init() {
        super.init(frame: .zero)
        wantsLayer = true
        // Stay concentric with whatever rounded container holds this view.
        cornerConfiguration = NSViewCornerConfiguration.uniformCorners(
            radius: NSViewCornerRadius.containerConcentric
        )
    }

    required init?(coder: NSCoder) { fatalError("init(coder:) has not been implemented") }
}

import AppKit

final class PeopleTableController: NSViewController, NSTableViewDelegate, NSTableViewDataSource {
    let tableView = NSTableView()
    var people: [String] = ["Ada", "Grace", "Alan"]
    private let cellID = NSUserInterfaceItemIdentifier("NameCell")

    func numberOfRows(in tableView: NSTableView) -> Int { people.count }

    func tableView(_ tableView: NSTableView, viewFor tableColumn: NSTableColumn?, row: Int) -> NSView? {
        let cell = tableView.makeView(withIdentifier: cellID, owner: self) as? NSTableCellView ?? {
            let view = NSTableCellView()
            let text = NSTextField(labelWithString: "")
            text.translatesAutoresizingMaskIntoConstraints = false
            view.addSubview(text)
            view.textField = text
            view.identifier = cellID
            NSLayoutConstraint.activate([
                text.leadingAnchor.constraint(equalTo: view.leadingAnchor, constant: 4),
                text.centerYAnchor.constraint(equalTo: view.centerYAnchor)
            ])
            return view
        }()
        cell.textField?.stringValue = people[row]
        return cell
    }
}

import AppKit

final class MainSplitController: NSSplitViewController {
    override func viewDidLoad() {
        super.viewDidLoad()

        let sidebar = NSSplitViewItem(sidebarWithViewController: SidebarController())
        sidebar.allowsFullHeightLayout = true
        sidebar.minimumThickness = 180

        let content = NSSplitViewItem(viewController: ContentController())

        let inspector = NSSplitViewItem(inspectorWithViewController: InspectorController())
        inspector.canCollapse = true

        addSplitViewItem(sidebar)
        addSplitViewItem(content)
        addSplitViewItem(inspector)
    }
}

final class SidebarController: NSViewController { override func loadView() { view = NSView() } }
final class ContentController: NSViewController { override func loadView() { view = NSView() } }
final class InspectorController: NSViewController { override func loadView() { view = NSView() } }
